"""Refund credit notes for the returns desk."""

RESTOCK_FEE_TIERS = ((20000, 0.15), (5000, 0.10), (0, 0.05))
CURRENCY_LOCK_HOURS = 48


class CreditError(Exception):
    """Raised when a credit note cannot be raised."""


def restock_fee(amount_cents):
    """Return the restocking fee for a refunded amount."""
    for threshold, rate in RESTOCK_FEE_TIERS:
        if amount_cents >= threshold:
            return int(amount_cents * rate)
    return 0


def credit_note(amount_cents, fee_cents):
    """Return the net credit for a refund after the restocking fee."""
    if fee_cents > amount_cents:
        raise CreditError("fee exceeds the credit amount")
    return amount_cents - fee_cents


def receipt_link(order_id, receipt_id):
    """Return the canonical link between an order and its receipt."""
    return "%s/%s" % (order_id, receipt_id)

