"""Weekly first-response load report for the support desk.

Sweeps every tickets-*.csv under the project tree and prints the total
overdue first-response minutes per queue. Safe to launch from any
directory.
"""
import csv
from pathlib import Path

BASE = Path(__file__).resolve().parent


def rows_of(path):
    with open(path, newline="", encoding="utf-8") as fh:
        return list(csv.DictReader(fh))


def main():
    overdue = {}
    for path in sorted(BASE.rglob("tickets-*.csv")):
        for row in rows_of(path):
            if row["first_response_ok"] != "no":
                continue
            queue = row["queue"]
            overdue[queue] = overdue.get(queue, 0) + row["first_response_minutes"]
    print("queue,overdue_minutes")
    for queue in sorted(overdue):
        print("%s,%d" % (queue, overdue[queue]))
    print("total,%d" % sum(overdue.values()))


if __name__ == "__main__":
    main()

